def solve(s):
    # Check if string contains any letters
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        # If no letters, reverse the string
        return s[::-1]
    else:
        # If has letters, swap case for letters and keep others as is
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result = [word for word in words if is_prime(len(word))]
    return " ".join(result)

